solvers
{
    "alpha.*"
    {
        nSubCycles      polynomial (0 2);
        cAlpha          1;
    }

    "pcorr.*"
    {
        solver          PCG;
        preconditioner
        {
            preconditioner  GAMG;
            tolerance       1e-05;
